        # kernel for performance. Thresholds calibrated from 100 iterations on CPU.
        cpu_bf16_cast = device == "cpu" and F.has_avx512bf16() and dtype in (torch.float16, torch.float32)
        if cpu_bf16_cast:
            thresholds = {
